import inspect
from rich.repr import rich_repr

class CustomClass:
    def __init__(self, x):
        self.x = x

    def __eq__(self, other):
        return True

@rich_repr
class MyClass:
    def __init__(self, x):
        self.x = x

def test_custom_class_eq():
    # Create a parameter that has a custom __eq__ returning True
    # We need to mock a Parameter object or find a way to make 
    # inspect.Parameter.empty == something else.
    # Actually, the issue is that if we have a class that overrides __eq__,
    # and that class is used as a default value in __init__,
    # then param.default == param.empty might be True if the custom class
    # returns True for everything.

    class AlwaysTrue:
        def __eq__(self, other):
            return True

    @rich_repr
    class TestClass:
        def __init__(self, x=AlwaysTrue()):
            self.x = x

    # If the bug exists, param.default == param.empty will be True
    # because AlwaysTrue() == inspect.Parameter.empty is True.
    # Then it will yield getattr(self, param.name) instead of (name, value, default).

    obj = TestClass(AlwaysTrue())
    # We can check what __rich_repr__ yields.
    results = list(obj.__rich_repr__())

    # Expected: (name, value, default) because it HAS a default.
    # Actual (buggy): value because it thinks it has NO default.

    assert len(results) == 1
    assert isinstance(results[0], tuple)
    assert len(results[0]) == 3
    assert results[0][0] == "x"

if __name__ == "__main__":
    try:
        test_custom_class_eq()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
        exit(1)
    except Exception as e:
        print(f"An error occurred: {e}")
        exit(1)
